// C++11 compliant constexpr pow function using recursion.
// Note the single 'return' statement with a ternary operator.
constexpr int pow(int base, int exp) noexcept {
    return exp == 0 ? 1 : base * pow(base, exp - 1);
}

// C++11 compliant usage
constexpr int val = pow(2, 10); // Evaluated at compile time

// The function can still be used at runtime as well
int run_exp = 5;
int run_val = pow(3, run_exp); // Evaluated at runtime
